    public void visitAssignExprTest() {
        Value operand = Value.newDecimalValue(10.0);
        VarExpr varExpr = new VarExpr(null, "x");
        AssingExpr assignExpr = new AssingExpr(null, varExpr, new DecimalExpr(null, operand));
        String output = PrettyPrintVisitor.exprToString(assignExpr);
        assertEquals("x = " + operand.toString(), output);
    }

