    public void visitUnaryExprTest() {
        Value operand = Value.newDecimalValue(10.0);
        DecimalExpr decimalExpr = new DecimalExpr(null, operand);
        UnaryExpr unaryExpr = new UnaryExpr(null, UnaryOp.MINUS, decimalExpr);
        String output = PrettyPrintVisitor.exprToString(unaryExpr);
        assertEquals("-" + operand.toString(), output);
    }

    @Test
    public void visitVarExprTest() {
        VarExpr varExpr = new VarExpr(null, "x");
        String output = PrettyPrintVisitor.exprToString(varExpr);
        assertEquals("x", output);
    }

    @Test
    public void visitDecimalExprTest() {
        Value operand = Value.newDecimalValue(10.0);
        DecimalExpr decimalExpr = new DecimalExpr(null, operand);
